style.css:
@-moz-document domain("youtube.com") {
/* 1. Targets the deep core containers and forces the image backdrop */
    html, 
    body, 
    ytd-app, 
    #page-manager, 
    #contentContainer.ytd-app, 
    #columns.ytd-watch-flexy {
        background-image: url("https://i.pinimg.com/736x/15/18/25/151825c7912bf899879b22bd57bfb2e7.jpg") !important;
        background-color: transparent !important;
        background-repeat: repeat !important;
        background-size: 280px !important;
        background-attachment: fixed !important;
    }

    /* 2. Disables YouTube's built-in dark/light surface gradients to let the image show through */
    ytd-browse, 
    ytd-watch-flexy, 
    #content.ytd-app,
    ytd-rich-grid-renderer,
    #page-manager.ytd-app {
        background: transparent !important;
        background-color: transparent !important;
    }
    
    /* 3. Frosted Glass Top Navigation Bar */
    ytd-masthead, 
    #background.ytd-masthead, 
    #container.ytd-masthead {
        background: rgba(30, 24, 20, 0.8) !important;
        backdrop-filter: blur(12px) !important;
    }

    /* 4. Semi-transparent black backers for the video grids so text remains easy to read */
    ytd-rich-item-renderer, 
    ytd-video-renderer, 
    ytd-compact-video-renderer,
    #meta.ytd-watch-metadata,
    #sections.ytd-comments {
        background: rgba(15, 12, 10, 0.75) !important;
        padding: 14px !important;
        border-radius: 12px !important;
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6) !important;
        border: 1px solid rgba(255, 255, 255, 0.05) !important;
    }

    /* 5. Makes the left sidebar slide-out container completely invisible */
    ytd-guide-renderer, 
    #sections.ytd-guide-renderer, 
    #contentContainer.app-drawer,
    ytd-guide-section-renderer {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 6. High-Contrast Text Fixes */
    #video-title, 
    #channel-name, 
    span, 
    #title,
    .yt-core-attributed-string {
        color: #f7f5f2 !important;
    }
}
